// Inputs come from parameters and the result is stored, preventing folding.
.visible .entry Qmul4Probe(
    .param .u64 output_ptr,
    .param .u16 packed_fp4,
    .param .u32 packed_scales
) {
  .reg .b16 %h1;
  .reg .b32 %r<3>;
  .reg .b64 %rd1;

  ld.param.u64 %rd1, [output_ptr];
  ld.param.u16 %h1, [packed_fp4];
  ld.param.u32 %r1, [packed_scales];
  cvt.u32.u16 %r2, %h1;
  or.b32 %r2, %r2, %r1;
  st.global.u32 [%rd1], %r2;
  ret;
}

