#include <cuda.h>

#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <iterator>
#include <string>
#include <thread>
#include <vector>

namespace {

void Check(CUresult result, const char* api, int index = -1) {
  if (result == CUDA_SUCCESS) {
    if (index < 0) {
      std::cout << "{\"event\":\"cuda_success\",\"api\":"
                << std::quoted(api) << "}" << std::endl;
    }
    return;
  }
  const char* name = "unknown";
  const char* description = "unknown";
  cuGetErrorName(result, &name);
  cuGetErrorString(result, &description);
  std::cout << "{\"event\":\"cuda_error\",\"api\":" << std::quoted(api)
            << ",\"index\":" << index << ",\"code\":" << result
            << ",\"name\":" << std::quoted(name)
            << ",\"description\":" << std::quoted(description)
            << "}" << std::endl;
  // An instruction fault invalidates the context. Process exit owns cleanup;
  // never reuse the context or issue further CUDA work after a failed call.
  std::_Exit(20);
}

struct Input {
  uint32_t fp4;
  uint32_t scales;
  uint32_t expected;
};
static_assert(sizeof(Input) == 12);

}  // namespace

int main(int argc, char** argv) {
  if (argc != 5) return 2;
  const std::string mode = argv[2];
  if (mode != "xor" && mode != "or" && mode != "qmul4") return 2;
  const int limit = std::stoi(argv[4]);
  if (limit <= 0 || limit > 4096) return 2;
  std::ifstream image_file(argv[1], std::ios::binary);
  std::vector<char> image((std::istreambuf_iterator<char>(image_file)), {});
  if (image.size() < 64) return 2;
  std::ifstream input_file(argv[3], std::ios::binary);
  std::vector<Input> inputs(limit);
  input_file.read(reinterpret_cast<char*>(inputs.data()),
                  static_cast<std::streamsize>(inputs.size() * sizeof(Input)));
  if (!input_file) return 2;

  Check(cuInit(0), "cuInit");
  int driver_version = 0;
  Check(cuDriverGetVersion(&driver_version), "cuDriverGetVersion");
  CUdevice device;
  Check(cuDeviceGet(&device, 0), "cuDeviceGet");
  char device_name[256] = {};
  Check(cuDeviceGetName(device_name, sizeof(device_name), device),
        "cuDeviceGetName");
  int major = 0;
  int minor = 0;
  Check(cuDeviceGetAttribute(&major,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
                            device), "cuDeviceGetAttribute-major");
  Check(cuDeviceGetAttribute(&minor,
                            CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
                            device), "cuDeviceGetAttribute-minor");
  std::cout << "{\"event\":\"device\",\"name\":"
            << std::quoted(device_name) << ",\"major\":" << major
            << ",\"minor\":" << minor
            << ",\"driver_version\":" << driver_version << "}" << std::endl;
  if (major != 11 || minor != 0) return 3;
  CUcontext context;
  Check(cuCtxCreate(&context, nullptr, CU_CTX_SCHED_BLOCKING_SYNC, device),
        "cuCtxCreate");
  // Permit the repository guard to observe this owned context before launch.
  std::this_thread::sleep_for(std::chrono::milliseconds(1250));

  CUmodule module;
  Check(cuModuleLoadDataEx(&module, image.data(), 0, nullptr, nullptr),
        "cuModuleLoadDataEx");
  CUfunction function;
  Check(cuModuleGetFunction(&function, module, "Qmul4Probe"),
        "cuModuleGetFunction");
  int binary_version = 0;
  Check(cuFuncGetAttribute(&binary_version, CU_FUNC_ATTRIBUTE_BINARY_VERSION,
                          function), "cuFuncGetAttribute-binary");
  std::cout << "{\"event\":\"binary_version\",\"value\":"
            << binary_version << "}" << std::endl;
  if (binary_version != 110) return 3;
  CUdeviceptr allocation;
  Check(cuMemAlloc(&allocation, 3 * sizeof(uint32_t)), "cuMemAlloc");
  CUdeviceptr output = allocation + sizeof(uint32_t);
  int mismatches = 0;
  for (int i = 0; i < limit; ++i) {
    uint16_t packed = static_cast<uint16_t>(inputs[i].fp4);
    uint32_t scales = inputs[i].scales;
    uint32_t expected = inputs[i].expected;
    if (mode == "xor") expected = packed ^ scales;
    if (mode == "or") expected = packed | scales;
    uint32_t data[3] = {0xdeadbeefu, 0xa5a5a5a5u, 0x12345678u};
    Check(cuMemcpyHtoD(allocation, data, sizeof(data)), "cuMemcpyHtoD", i);
    void* params[] = {&output, &packed, &scales};
    Check(cuLaunchKernel(function, 1, 1, 1, 1, 1, 1, 0, nullptr,
                         params, nullptr), "cuLaunchKernel", i);
    if (i == 0) {
      std::cout << "{\"event\":\"launch_accepted\",\"index\":0}"
                << std::endl;
    }
    Check(cuCtxSynchronize(), "cuCtxSynchronize", i);
    Check(cuMemcpyDtoH(data, allocation, sizeof(data)), "cuMemcpyDtoH", i);
    const bool guards_ok = data[0] == 0xdeadbeefu && data[2] == 0x12345678u;
    const bool match = guards_ok && data[1] == expected;
    mismatches += !match;
    std::cout << "{\"event\":\"sample\",\"index\":" << i
              << ",\"fp4\":" << packed << ",\"scales\":" << scales
              << ",\"expected\":" << expected
              << ",\"actual\":" << data[1]
              << ",\"guards_ok\":" << (guards_ok ? "true" : "false")
              << ",\"match\":" << (match ? "true" : "false")
              << "}" << std::endl;
    if (!match) break;
  }
  Check(cuMemFree(allocation), "cuMemFree");
  Check(cuModuleUnload(module), "cuModuleUnload");
  Check(cuCtxDestroy(context), "cuCtxDestroy");
  std::cout << "{\"event\":\"completed\",\"mode\":" << std::quoted(mode)
            << ",\"planned_samples\":" << limit
            << ",\"mismatches\":" << mismatches << "}" << std::endl;
  return mismatches ? 30 : 0;
}

